script.code:
			function ConvertScientificNumber()
			{
				var num = Number(window.external.GetCsvColumnValue("Total poste non décomposé").replace(",","."));
    			return num.toFixed(6);
			}

			function GetUnit()
			{
				var unitVal = window.external.GetCsvColumnValue("Unité français");
				if (unitVal.indexOf("kgCO2e/") === -1)
				{
					return unitVal;
				}
				else
				{
					return unitVal.substring(unitVal.indexOf("/")+1);
				}
			}

			function GetLocalization()
			{
				var columns = ["Sous-localisation géographique français", "Sous-localisation géographique anglais", "Sous-localisation géographique espagnol", "Localisation géographique"];

				for (var i = 0; i < columns.length; i++)
				{
					var column = window.external.GetCsvColumnValue(columns[i]);
					if (column && column != "")
					{
						return column;
					}
				}

				return "";
			}
